      "content": "{\n  \"name\": \"ccgui-next\",\n  \"private\": true,\n  \"version\": \"1.1.7\",\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@10.29.3\",\n  \"scripts\": {\n    \"build\": \"tsc --noEmit && vite build\",\n    \"test\": \"vitest run\",\n    \"plugin-skill:docs\": \"node --experimental-strip-types scripts/build-plugin-skill-docs.ts\",\n    \"build:mac\": \"./scripts/build-signed-macos.sh\",\n    \"build:mac:skip-notarize\": \"SKIP_NOTARIZE=1 ./scripts/build-signed-macos.sh\",\n    \"preview\": \"vite preview\",\n    \"dev\": \"tauri dev\"\n  },\n  \"dependencies\": {\n    \"@ccgui/plugin-sdk\": \"workspace:*\",\n    \"@codemirror/language\": \"^6.12.3\",\n    \"@codemirror/language-data\": \"^6.5.2\",\n    \"@codemirror/state\": \"^6.7.2\",\n    \"@codemirror/view\": \"^6.43.10\",\n    \"@dagrejs/dagre\": \"^3.1.1\",\n    \"@fontsource-variable/inter\": \"^5.2.0\",\n    \"@fontsource-variable/jetbrains-mono\": \"^5.2.0\",\n    \"@lobehub/icons-static-svg\": \"^1.95.0\",\n    \"@streamdown/cjk\": \"^1.0.3\",\n    \"@streamdown/code\": \"^1.1.1\",\n    \"@streamdown/math\": \"^1.0.2\",\n    \"@streamdown/mermaid\": \"^1.0.2\",\n    \"@tanstack/react-virtual\": \"^3\",\n    \"@tauri-apps/api\": \"^2\",\n    \"@tauri-apps/plugin-dialog\": \"^2.7.3\",\n    \"@tauri-apps/plugin-process\": \"^2.3.1\",\n    \"@tauri-apps/plugin-updater\": \"^2.11.0\",\n    \"@uiw/react-codemirror\": \"^4\",\n    \"@xterm/addon-fit\": \"^0.11.0\",\n    \"@xterm/addon-webgl\": \"^0.19.0\",\n    \"@xterm/xterm\": \"^6.0.0\",\n    \"@xyflow/react\": \"^12.11.6\",\n    \"dompurify\": \"^3.4.14\",\n    \"i18next\": \"^24\",\n    \"katex\": \"^0.16.47\",\n    \"lucide-react\": \"^0.562.0\",\n    \"motion\": \"^12.43.0\",\n    \"qrcode.react\": \"^4.2.0\",\n    \"react\": \"^18.3.1\",\n    \"react-aria-components\": \"^1.21.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"react-i18next\": \"^15\",\n    \"react-markdown\": \"^9\",\n    \"react-router-dom\": \"^7\",\n    \"react-s